import React from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faShoppingCart } from '@fortawesome/free-solid-svg-icons';
import './ZapatosCard.css';

const ZapatosCard = ({key,
  id, 
  marca,
  costo,
  color,
  modelo,
  calidad,
  descripcion,
  url,
  talla}) => {

  return (
    <div className="zapatos-card" title={id}>
      <img
        src={url}
        alt="Zapato"
        className="zapatos-image"
      />
      <div className="zapatos-info">

        <div className='titulo-zapato'><p className='black-text'>Marca: </p> {marca}</div>
        <div  className="zapatos-price">
              <div className='parrafo-flex'><p className='black-text'>Calidad:</p> {calidad}</div>
              <div >Tallas: {talla}</div>
              <div>Categoria: {modelo}</div>
              <div>Color: {color}</div>
              <div>Costo: ${costo}</div>
        </div>
     
        <button className="zapatos-btn" >
            <FontAwesomeIcon icon={faShoppingCart} className="cart-icon" />
            Agregar al carrito
          </button>
      </div>
    </div>
  );
}

export default ZapatosCard;
